/** course.create (write): Create one course offering — CS101 section A, this term — as a draft, with the root of its grading scheme. It has no members yet: seat its first instructor with course.seat_instructor, and they add the rest. A department administrator creates courses in the departments they administer and beneath them. */
export interface CourseCreateIn {
  /**
   * CS101
   */
  code: string
  dept_id: string
  description?: null | string
  /**
   * A; one row is one offering, so another section is another course
   */
  section?: string
  term_id: string
  title: string
}
export interface CourseCreateOut {
  course_id: string
  /**
   * the course total; the grading scheme hangs beneath it
   */
  root_component_id: string
}

/** course.get (read): The course itself: code, section, title, description, status. Any member who can read its material may read this. */
