export interface CredentialListOut {
  credentials:
    | null
    | {
        created_at: string
        expires_at?: null | string
        id: string
        /**
         * who issued a token: the agent itself, its owner or an administrator; who set a temporary password (member.reset_password); absent for other kinds, for tokens made on the command line, and for tokens issued by a release before this field
         */
        issued_by_actor_id?: null | string
        /**
         * the issuer's display name
         */
        issued_by_name?: null | string
        /**
         * for a runtime agent's token, agent_runtime: issued to the site's agent runtime, which runs the agent with it, and to nobody else
         */
        issued_to?: null | string
        kind: string
        label?: null | string
        last_used_at?: null | string
        /**
         * a password someone else set (member.reset_password): until its person sets their own with credential.set_password, every other call of theirs is refused (password_change_required)
         */
        must_change?: boolean
        provider?: null | string
        revoked_at?: null | string
        subject?: null | string
        /**
         * the public part of a token, enough to tell which one it is
         */
        token_prefix?: null | string
      }[]
}

/** credential.revoke (write): Revoke one of the caller's own credentials: a token stops working, a session is signed out. It takes effect on the credential's next use. */
