/** member.pause (write): Pause a member: every call they make is denied from now until they are resumed. The same membership, with its id, permissions and history, carries on afterwards — for an agent, the same relationship. Their pending proposals stay queued but cannot be approved while they are paused. */
export interface MemberPauseIn {
  /**
   * the course this call is about
   */
  course_id: string
  member_id: string
}
export interface MemberPauseOut {
  ok: boolean
}

/** member.remove (write): Remove a member from the course. Everything they did stays on record, and whatever they had proposed that nobody has decided yet is cancelled. Seating the same actor again later is a new membership with a new id: for an agent, a fresh start. */
export interface MemberRemoveIn {
  /**
   * the course this call is about
   */
  course_id: string
  member_id: string
}
export interface MemberRemoveOut {
  cancelled_proposals: number
}

/** member.rescope (write): Change which students and assignments a member's permissions reach, or when the membership expires. 'listed' with an empty list reaches nobody. Widening a scope, or extending or clearing an expiry, is a grant: everything the member will then hold must be within what you hold yourself. Narrowing is always allowed. */
export interface MemberRescopeIn {
  assignment_scope?: null | string
  clear_expiry?: boolean
  /**
   * the course this call is about
   */
  course_id: string
  expires_at?: null | string
  /**
   * replaces the list; omit to keep it
   */
  listed_assignments?: null | string[]
  /**
   * replaces the list; omit to keep it
   */
  listed_students?: null | string[]
  member_id: string
  student_scope?: null | string
}
export interface MemberRescopeOut {
  ok: boolean
}

/** member.reset_password (write): Give a student of the course a new, temporary password, for one who has forgotten theirs and has no email to reset it by. It is returned once, to hand to them; only its hash is kept. Every session they have is signed out, and the next time they sign in, with it, they must set a password of their own before anything else. For people who manage the course's members without approval (member_manage autonomous); never by proposal (not_by_proposal), and never by an agent (people_only), which is never handed a password. Only for a person's active student seat in this course (not_a_person, not_a_student, seat_not_active) whose account reaches nothing beyond it: seated as a student and nothing else in every course (seated_other_than_student), holding no platform role (platform_role), administering no department (administers), signing in by no identity provider (sso_linked), and with a login ID or an email to sign in with (no_sign_in_name); and whose seat holds nothing you do not (beyond_your_seat). Anyone else's is an administrator's to reset (actor.invite). */
export interface MemberResetPasswordIn {
  /**
   * the course this call is about
   */
  course_id: string
  member_id: string
}
export interface MemberResetPasswordOut {
  actor_id: string
  display_name: string
  /**
   * what they sign in with, if they have a login ID; otherwise it is their email, which they know
   */
  login_id?: null | string
  member_id: string
  /**
   * how many sessions of theirs were signed out
   */
  sessions_ended: number
  /**
   * for you to hand to the student; shown once: it is not stored, and a replay of this call comes back without it
   */
  temporary_password?: string
}

/** member.resume (write): Resume a paused member, exactly as they were. That is a grant of everything they hold, which must be within what you hold yourself. */
export interface MemberResumeIn {
  /**
   * the course this call is about
   */
  course_id: string
  member_id: string
}
export interface MemberResumeOut {
  ok: boolean
}

/** member.set_role (write): Change a seat's roster role: student, ta, instructor, observer or assistant. The role is a fact of the roster and nothing more: it decides who is on the gradebook and who hands work in, never what a seat may do. Its permissions and scope stay exactly as they are, since authorization never reads role; change them with member.update_perms and member.rescope. A student made a TA keeps everything they handed in and every grade and total they were given, readable as before, and work already handed in may still be graded; from then on they are off the roster: not listed as a student, not marked missing when a due date passes, handing in nothing new and given no new grade on a component. Someone made a student is on the roster and may hand work in. Not on your own seat, and not on a delegate's, which is always assistant; a delegate that manages the course's members changes the role of neither its principal's seat nor its principal's other agents' (not_your_principal). Giving a seat the role it has changes nothing and says so (changed: false). */
export interface MemberSetRoleIn {
  /**
   * the course this call is about
   */
  course_id: string
  member_id: string
  /**
   * student, instructor, ta, observer or assistant
   */
  role: string
}
export interface MemberSetRoleOut {
  /**
   * false when the seat already had the role: nothing was done
   */
  changed: boolean
  /**
   * the role the seat had before this call
   */
  previous: string
  role: string
}

/** member.update_perms (write): Change individual permissions on a member. It takes effect on their next call: nothing is cached. Raising one is a grant: everything the member will then hold — every permission, over their whole scope, for as long as their seat lasts — must be within what you hold yourself, and within what the seat may hold at all (perm_ceilings in member.get; above it the refusal gives the same reason code). Lowering is always allowed. */
export interface MemberUpdatePermsIn {
  /**
   * the course this call is about
   */
  course_id: string
  member_id: string
  /**
   * the permissions to change, by name; the rest stay as they are
   */
  perms: {
    [k: string]: string | undefined
  }
}
export interface MemberUpdatePermsOut {
  ok: boolean
}

/** member.update_perms_bulk (write): Change individual permissions on every seat with one roster role — every student, say — other than your own, removed and expired seats left out. Each change is held to the rules of member.update_perms: raising a level is a grant that must be within what you hold yourself, over that member's whole scope, and within what the seat may hold at all (perm_ceilings): an agent's action_decide goes no higher than confirm_required. If any one seat cannot be changed, none is, and the refusal names it (member_id) and says why (reason). It changes the seats there are now: a seat added later takes its preset's levels, so repeat the call, give the levels to member.add, or use a department preset. A delegate's call is refused whole (not_your_principal) when the role takes in its principal's seat or another agent of its principal's. */
export interface MemberUpdatePermsBulkIn {
  /**
   * the course this call is about
   */
  course_id: string
  /**
   * the permissions to change, by name; the rest stay as they are
   */
  perms: {
    [k: string]: string | undefined
  }
  /**
   * every seat with this roster role: student, instructor, ta, observer or assistant
   */
  role: string
}
export interface MemberUpdatePermsBulkOut {
  /**
   * how many seats were changed
   */
  updated: number
}

/** memory.forget (write): Delete an entry of your memory for good: wrong, out of date, or no longer wanted. It works for anything you may reach, a shared entry or a proposal of yours included, and whether or not your memory is switched on. An entry about an asker needs the conversation you are answering them in. */
